// This minute's Slack reads. No LLM here. Reads: channel history, replies in active/proposal threads,
// reactions on pending bot proposals (post previews + engagement ideas, last 48 h, from client1-state).
const s = $getWorkflowStaticData('global');
const CH = 'C0000000001';
const now = Date.now() / 1000;
const tick = $('Helper: tick').first().json || {};
const pending = (tick.ok && Array.isArray(tick.pending)) ? tick.pending : [];
if (!s.lastTs) s.lastTs = now.toFixed(6);
s.threads = s.threads || {};
for (const [k, v] of Object.entries(s.threads)) if (now - v > 48 * 3600) delete s.threads[k];
const reqs = [{ kind: 'history', endpoint: 'conversations.history', qs: { channel: CH, oldest: s.lastTs, limit: 100, inclusive: false } }];
s.onboard = s.onboard || {};
for (const [k, v] of Object.entries(s.onboard)) if (now - v > 7 * 86400) delete s.onboard[k];
const threads = Object.keys(s.onboard).slice(0, 4);
for (const k of Object.entries(s.threads).sort((a, b) => b[1] - a[1]).slice(0, 8).map(x => x[0])) if (!threads.includes(k)) threads.push(k);
for (const p of pending) if (p.thread_ts && !threads.includes(p.thread_ts)) threads.push(p.thread_ts);
for (const ts of threads.slice(0, 14)) reqs.push({ kind: 'replies', endpoint: 'conversations.replies', qs: { channel: CH, ts, oldest: s.lastTs, limit: 100, inclusive: false } });
for (const p of pending.slice(0, 20)) reqs.push({ kind: 'reactions', endpoint: 'reactions.get', qs: { channel: CH, timestamp: p.slack_ts, full: true } });
// Viral plan: ✅ / ⏭ on action-list task messages (helper rotates which ones, max 10 a minute)
for (const ts of ((tick.ok && Array.isArray(tick.coach_open)) ? tick.coach_open : []).slice(0, 10))
  reqs.push({ kind: 'coach_reactions', endpoint: 'reactions.get', qs: { channel: CH, timestamp: ts, full: true } });
return reqs.map((r, i) => ({ json: { ...r, startTs: s.lastTs, tick: i === 0 ? tick : undefined } }));

// Turns Slack data into work items. Only the owner (U0000000001) can approve/discard/edit; bot reactions are ignored.
// Each proposal message is acted on once per decision (static data 'acted'); client1-state enforces it again.
const s = $getWorkflowStaticData('global');
const BOT = 'U0000000002', OWNER = 'U0000000001', CH = 'C0000000001';
const plans = $('Plan Slack reads').all().map(i => i.json);
const tick = plans[0].tick || {};
const pending = (tick.ok && Array.isArray(tick.pending)) ? tick.pending : [];
const byTs = Object.fromEntries(pending.map(p => [p.slack_ts, p]));
const start = Number(plans[0].startTs);
const nowS = Date.now() / 1000;
s.done = s.done || []; s.threads = s.threads || {}; s.acted = s.acted || {}; s.notified = s.notified || [];
for (const [k, v] of Object.entries(s.acted)) if (nowS - v > 72 * 3600) delete s.acted[k];
const APPROVE = new Set(['white_check_mark', 'heavy_check_mark', 'ballot_box_with_check']);
const EDIT = new Set(['pencil2', 'pencil', 'memo', 'writing_hand']);
const DISCARD = new Set(['x', 'negative_squared_cross_mark']);
const APPROVE_RE = /^(:white_check_mark:|:heavy_check_mark:|✅|approved?\b|post it\b|publish( it)?\b|go ahead\b|ship it\b|yes,? (post|publish)|lgtm\b|ok,? post)/;
const DISCARD_RE = /^(:x:|❌|discard\b|cancel\b|scrap it\b|delete (it|the draft)\b|don'?t post\b|skip( it)?\b)/;
const out = [];
const terminal = ts => s.acted[ts + ':approve'] || s.acted[ts + ':discard'];
const APPROVERS = new Set(Array.isArray(tick.approvers) && tick.approvers.length ? tick.approvers : [OWNER]);
function batchDecide(ts, decision, eyes, user, withEyes) {
  // one typed message can answer several batch items: keyed per item + typed message; only the first op carries the 👀 receipt
  const key = ts + ':' + decision + ':' + eyes;
  if (s.acted[ts + ':discard'] || s.acted[key]) return;
  s.acted[key] = nowS; if (decision === 'discard') s.acted[ts + ':discard'] = nowS;
  out.push({ json: { route: 'op', eyes: withEyes ? eyes : undefined, payload: JSON.stringify({ op: 'decide', slack_ts: ts, decision, by: user, now: false, source: 'typed', ts: withEyes ? eyes : undefined, channel: CH }) } });
}
// typed batch answers (mirrors batches.parse_batch_text in client1-state; tested there)
const B_OK = '(?:approve|ok|yes|✅|:white_check_mark:|:heavy_check_mark:)', B_NO = '(?:skip|discard|no|❌|:x:)';
const B_NUMS = '((?:\\d\\s*(?:,|and|&|\\s)\\s*)*\\d)';
function parseBatch(text) {
  const t = String(text || '').replace(/\s+/g, ' ').trim(), low = t.toLowerCase();
  let mm = t.match(/^(\d)\s*[:.)]\s*(.{3,})$/);
  if (mm) return { action: 'edit', nums: [Number(mm[1])], text: mm[2].trim() };
  if (new RegExp('^(' + B_OK + '\\s+all|all\\s+' + B_OK + ')\\s*[!.]*$').test(low)) return { action: 'approve', nums: 'all' };
  if (new RegExp('^(' + B_NO + '\\s+all|all\\s+' + B_NO + ')\\s*[!.]*$').test(low)) return { action: 'discard', nums: 'all' };
  for (const [verb, act] of [[B_OK, 'approve'], [B_NO, 'discard']]) {
    mm = low.match(new RegExp('^' + verb + '\\s*' + B_NUMS + '\\s*[!.]*$')) || low.match(new RegExp('^' + B_NUMS + '\\s*' + verb + '\\s*[!.]*$'));
    if (mm) return { action: act, nums: [...new Set((mm[1].match(/\d/g) || []).map(Number))].sort((a, b) => a - b) };
  }
  return null;
}

function decide(ts, decision, now, src, eyes) {
  // Reactions act once per message. A TYPED 'approve' is keyed per typed message, so it can retry after a guardrail refusal
  // (cap, pause, content check); the helper's atomic state change still prevents any double publish.
  const key = ts + ':' + decision + (src === 'typed' ? ':' + eyes : '');
  const blocked = src === 'typed' ? (s.acted[ts + ':discard'] || s.acted[key]) : (terminal(ts) || s.acted[key]);
  if (blocked) { if (eyes) out.push({ json: { route: 'op', eyes, payload: JSON.stringify({ op: 'noop', ts: eyes, channel: CH, by: OWNER }) } }); return; }
  s.acted[key] = nowS; if (decision === 'discard') s.acted[ts + ':discard'] = nowS;   // discard is final either way
  out.push({ json: { route: 'op', eyes: eyes || undefined, payload: JSON.stringify({ op: 'decide', slack_ts: ts, decision, by: OWNER, now: !!now, source: src, ts: eyes || undefined, channel: CH }) } });
}
let maxTs = start, histOk = false; const seen = new Map();
$input.all().forEach((it, idx) => {
  const r = it.json, p = plans[idx] || {};
  if (p.kind === 'coach_reactions') {
    // client's ✅ (done) / ⏭ (skipped) on a coach task; bot reactions are ignored; done wins; each state acted on once
    if (!r || !r.ok) return;
    const msg = r.message || {};
    if (!(msg.bot_id || msg.user === BOT)) return;
    const users = new Set(Array.isArray(tick.coach_users) && tick.coach_users.length ? tick.coach_users : [OWNER]);
    const DONE = new Set(['white_check_mark', 'heavy_check_mark', 'ballot_box_with_check']);
    const SKIP = new Set(['black_right_pointing_double_triangle_with_vertical_bar', 'next_track_button', 'track_next', 'fast_forward']);
    const by = set => { for (const x of (msg.reactions || [])) { const n = String(x.name).replace(/::skin-tone-\d$/, ''); if (set.has(n)) { const u = (x.users || []).find(u => users.has(u)); if (u) return u; } } return null; };
    const ts = p.qs.timestamp, dU = by(DONE), sU = by(SKIP);
    const state = dU ? 'done' : (sU ? 'skipped' : '');
    if (state && !s.acted[ts + ':coach:' + state]) {
      s.acted[ts + ':coach:' + state] = nowS;
      out.push({ json: { route: 'op', payload: JSON.stringify({ op: 'coach_mark', slack_ts: ts, state, by: dU || sU, channel: CH }) } });
    }
    return;
  }
  if (p.kind === 'reactions') {
    if (!r || !r.ok) return;
    const ts = p.qs.timestamp, prop = byTs[ts];
    if (!prop) return;
    const msg = r.message || {};
    if (!(msg.bot_id || msg.user === BOT)) return;                       // approvals only count on the bot's own messages
    const mine = new Set(((r.message || {}).reactions || []).filter(x => (x.users || []).includes(OWNER)).map(x => String(x.name).replace(/::skin-tone-\d$/, '')));
    const has = set => [...mine].some(n => set.has(n));
    if (has(DISCARD)) decide(ts, 'discard', false, 'reaction');            // ❌ wins if both are present (safe side)
    else if (has(APPROVE)) decide(ts, 'approve', false, 'reaction');
    else if (has(EDIT) && prop.state === 'pending' && (prop.kind === 'post' || prop.batch)) decide(ts, 'edit', false, 'reaction');
    return;
  }
  if (!r || !r.ok) { if (p.kind === 'replies' && r && r.error === 'thread_not_found') delete s.threads[p.qs.ts]; return; }
  if (p.kind === 'history') histOk = true;
  for (const m of (r.messages || [])) { const ts = Number(m.ts); if (!(ts > start)) continue; if (ts > maxTs) maxTs = ts; seen.set(m.ts, m); }
});
if (histOk) s.lastTs = maxTs.toFixed(6);
const latestPending = th => pending.filter(p => p.thread_ts === th).sort((a, b) => Number(b.slack_ts) - Number(a.slack_ts))[0];
for (const m of [...seen.values()].sort((a, b) => Number(a.ts) - Number(b.ts))) {
  if (m.bot_id || m.app_id || m.user === BOT || !m.user) continue;
  if (m.subtype && m.subtype !== 'thread_broadcast' && m.subtype !== 'file_share') continue;
  if (s.done.includes(m.ts)) continue;
  const text = String(m.text || '').trim();
  if (!text) continue;
  const thread = m.thread_ts || m.ts;
  s.threads[thread] = nowS; s.done.push(m.ts);
  const t = text.replace(/<@[A-Z0-9]+>/g, '').trim(), low = t.toLowerCase();
  const isOwner = m.user === OWNER;
  const op = o => out.push({ json: { route: 'op', eyes: m.ts, payload: JSON.stringify({ ...o, by: m.user, channel: CH, thread_ts: thread, ts: m.ts }) } });
  let mm;
  s.onboard = s.onboard || {};
  const ob = c => out.push({ json: { route: 'onboard', eyes: m.ts, client: 'client1', channel: CH, thread_ts: thread, ts: m.ts, user: m.user, text: text.slice(0, 3000), mode: c, dry_run: false } });
  // Pasted passwords / keys: never routed to the LLM, onboarding or memory. The helper warns (or deletes if scopes allow) and tells the owner.
  const SECRET = /(\b(my |the |our )?(pass(word|wd|code)?|pwd|login pin|otp)\b\s*(is|=|:|-)\s*\S+|xox[abpers]-[A-Za-z0-9-]{8,}|\bsk-[A-Za-z0-9_-]{16,}|\bAKIA[0-9A-Z]{16}\b|\bgh[pousr]_[A-Za-z0-9]{20,}|\b(api[_ -]?key|secret|token)\b\s*(is|=|:)\s*\S{8,})/i;
  if (SECRET.test(t)) { op({ op: 'secret' }); continue; }
  if (/^(pause|stop) (everything|all)\b/.test(low)) { op({ op: 'pause_all', text: `<@${m.user}> said '${t.slice(0, 40)}' in #client1` }); continue; }
  if (/^(resume|unpause|restart) (everything|all)\b/.test(low)) { op({ op: 'resume_all' }); continue; }
  if (/^(limits|usage|show (me )?(the )?limits|my limits)\s*[?!.]*$/.test(low)) { op({ op: 'limits' }); continue; }
  if (/^weekly report\b/.test(low)) { op({ op: 'weekly_report' }); continue; }
  if (/^(sign[- ]?in link|send (me )?a sign[- ]?in link)\b/.test(low)) { op({ op: 'signin_request' }); continue; }
  if (/^start onboarding\b/.test(low)) { s.onboard[thread] = nowS; ob('start'); continue; }
  if (s.onboard[thread] && /^(stop|cancel) onboarding\b/.test(low)) { delete s.onboard[thread]; ob('cancel'); continue; }
  if (s.onboard[thread] && m.thread_ts && m.thread_ts !== m.ts && !/^(remember\s*[:\-]|pause engagement|resume engagement)/.test(low)) { s.onboard[thread] = nowS; ob('answer'); continue; }
  if (/^pause engagement\b/.test(low)) { op({ op: 'pause', text: `<@${m.user}> said 'pause engagement' in #client1` }); continue; }
  if (/^resume engagement\b/.test(low)) { op({ op: 'resume' }); continue; }
  if ((mm = t.match(/^remember\s*[:\-]\s*([\s\S]+)/i))) { op({ op: 'remember', text: mm[1].trim() }); continue; }
  if (/^engagement status\b/.test(low)) { op({ op: 'engage_status' }); continue; }
  // Viral plan / coach commands (the helper checks who may do what)
  if ((mm = low.match(/^switch plan (?:to )?([a-z]+)\b/))) { op({ op: 'switch_plan', plan: mm[1] }); continue; }
  if (/^(action list|coach now|(send|give) (me )?(an |my |a new )?action list)\s*(now|please)?\s*[?!.]*$/.test(low)) { op({ op: 'coach_now' }); continue; }
  if (/^shorter (action )?lists?\b/.test(low)) { op({ op: 'coach_size', size: 'shorter' }); continue; }
  if (/^(normal|longer) (action )?lists?\b/.test(low)) { op({ op: 'coach_size', size: 'normal' }); continue; }
  if ((mm = low.match(/^report (?:a )?warning (?:on |from )?(x|twitter|linkedin|facebook|fb)\b/))) { op({ op: 'ramp_warning', platform: mm[1], text: t.slice(0, 300) }); continue; }
  if (/^(my score|coach status|action list status)\s*[?!.]*$/.test(low)) { op({ op: 'coach_status' }); continue; }
  if (/^(suggest engagement|engagement now|engage now|find posts to engage)\b/.test(low)) { op({ op: 'engage_now' }); continue; }

  // Draft batches (2026-10-12): commands, and typed answers inside a batch thread ('1 ✅', 'approve 1, 3', '2 ❌', 'approve all', '3: new text')
  if (/^watchlist\s*[?!.]*$/.test(low)) { op({ op: 'watchlist' }); continue; }
  if ((mm = low.match(/^watch\s+@?([a-z0-9_]{1,15})\b/))) { op({ op: 'watch', handle: mm[1], text: t.slice(0, 80) }); continue; }
  if ((mm = low.match(/^unwatch\s+@?([a-z0-9_]{1,15})\b/))) { op({ op: 'unwatch', handle: mm[1], text: t.slice(0, 80) }); continue; }
  if (/^(comment on|reply to)\s+<?https?:\/\//i.test(t)) { op({ op: 'batch_target', text: t.slice(0, 700) }); continue; }
  if (/^(next batch|new batch|(send|give) (me )?(a |the )?(next |new )?batch)( now| please)?\s*[?!.]*$/.test(low)) { op({ op: 'batch_next' }); continue; }
  if (/^(pause|stop) (the )?(draft )?batch(es)?\b/.test(low)) { op({ op: 'batch_pause' }); continue; }
  if (/^(resume|restart|start) (the )?(draft )?batch(es)?\b/.test(low)) { op({ op: 'batch_resume' }); continue; }
  if (/^(batch(es)? status|draft batch(es)?( status)?)\s*[?!.]*$/.test(low)) { op({ op: 'batch_status' }); continue; }
  const bmap = (m.thread_ts && m.thread_ts !== m.ts) ? ((tick.batches || {})[m.thread_ts] || null) : null;
  if (bmap && APPROVERS.has(m.user)) {
    const bc = parseBatch(t);
    if (bc && bc.action === 'edit') { op({ op: 'batch_edit', n: bc.nums[0], text: bc.text.slice(0, 1500) }); continue; }
    if (bc) {
      const nums = bc.nums === 'all' ? Object.keys(bmap).map(Number).sort((a, b) => a - b) : bc.nums;
      let first = true, any = false;
      for (const n of nums) {
        const it = bmap[String(n)];
        if (!it || (bc.nums === 'all' && !['pending', 'editing'].includes(it.state))) continue;
        any = true; batchDecide(it.ts, bc.action, m.ts, m.user, first); first = false;
      }
      if (!any) op({ op: 'batch_help' });
      continue;
    }
    if (APPROVE_RE.test(low) || DISCARD_RE.test(low)) {
      const open = Object.values(bmap).filter(it => it.state === 'pending');
      if (open.length === 1) batchDecide(open[0].ts, APPROVE_RE.test(low) ? 'approve' : 'discard', m.ts, m.user, true);
      else op({ op: 'batch_help' });
      continue;
    }
  }
  const prop = (m.thread_ts && m.thread_ts !== m.ts) ? latestPending(m.thread_ts) : null;
  if (prop && isOwner && APPROVE_RE.test(low)) { decide(prop.slack_ts, 'approve', /\bnow\b/.test(low), 'typed', m.ts); continue; }
  if (prop && isOwner && DISCARD_RE.test(low)) { decide(prop.slack_ts, 'discard', false, 'typed', m.ts); continue; }
  const editingPost = (m.thread_ts && m.thread_ts !== m.ts) ? pending.find(p => p.thread_ts === m.thread_ts && p.kind === 'post' && p.state === 'editing') : null;
  const context = (prop && prop.kind === 'post' && prop.state === 'editing') ? 'editing:' + prop.slack_ts : (editingPost ? 'editing:' + editingPost.slack_ts : '');
  out.push({ json: { route: 'handler', eyes: m.ts, channel: CH, ts: m.ts, thread_ts: thread, user: m.user, text: text.slice(0, 4000), dry_run: false, announce: '', context } });
}
for (const o of (tick.outbox || [])) {
  if (s.notified.includes(o.id)) continue;
  s.notified.push(o.id);
  out.push({ json: { route: 'op', payload: JSON.stringify({ op: 'notify', id: o.id, channel: o.channel || CH, thread_ts: o.thread_ts || '', text: o.text }) } });
}
s.done = s.done.slice(-300); s.notified = s.notified.slice(-200);
return out;   // empty -> run ends: no LLM call when idle
